import type { TokenUsage } from '../../shared/contract'

/**
 * Tokens sent to and generated by the model. Input counts cache reads and writes because
 * harnesses that cache (Claude, Copilot) report only a handful of uncached input tokens per call;
 * output counts reasoning.
 */
export function tokenIO(t: TokenUsage): { input: number; output: number } {
  return { input: t.input + t.cacheRead + t.cacheWrite, output: t.output + t.reasoning }
}

/** Multi-line breakdown for tooltips. */
export function tokenBreakdown(t: TokenUsage): string {
  const n = (v: number) => v.toLocaleString('en-US')
  return [
    `Input ${n(t.input)} · Cache read ${n(t.cacheRead)} · Cache write ${n(t.cacheWrite)}`,
    `Output ${n(t.output)} · Reasoning ${n(t.reasoning)}`,
  ].join('\n')
}

/** The rate looks back this far. */
export const RATE_WINDOW_MS = 2 * 60_000
/** Shortest span a rate is averaged over, so one burst right after the baseline doesn't read as a spike. */
const MIN_SPAN_MS = 15_000

interface Sample { ts: number; out: number }

/**
 * Output tokens per minute for live sessions, from the session totals the client sees over time.
 * Samples are kept only when the total changes; the oldest sample before the window is kept as a
 * baseline so the first increase after a quiet spell still has something to compare against.
 */
export class TokenRateTracker {
  private readonly samples = new Map<string, Sample[]>()

  record(id: string, ts: number, out: number): void {
    const list = this.samples.get(id)
    if (!list) {
      this.samples.set(id, [{ ts, out }])
      return
    }
    const last = list[list.length - 1]!
    if (out === last.out) return
    if (out < last.out) {
      // the source re-read the session (e.g. log rotation): start over
      this.samples.set(id, [{ ts, out }])
      return
    }
    list.push({ ts, out })
    while (list.length > 2 && list[1]!.ts <= ts - RATE_WINDOW_MS) list.shift()
  }

  /**
   * Output tokens per minute over the last window, or null when nothing was generated in it.
   * The span runs from the baseline sample, clamped to the window, so a burst after a quiet spell
   * is averaged over the window rather than the whole quiet period.
   */
  rate(id: string, now: number): number | null {
    const list = this.samples.get(id)
    if (!list || list.length < 2) return null
    const last = list[list.length - 1]!
    if (last.ts <= now - RATE_WINDOW_MS) return null
    const base = list[0]!
    const delta = last.out - base.out
    if (delta <= 0) return null
    const span = Math.min(RATE_WINDOW_MS, Math.max(MIN_SPAN_MS, now - base.ts))
    return (delta / span) * 60_000
  }

  forget(id: string): void {
    this.samples.delete(id)
  }

  clear(): void {
    this.samples.clear()
  }
}

/** App-wide tracker, fed by the store from bootstrap and `sessions` stream frames. */
export const tokenRates = new TokenRateTracker()
